const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const K = nextInt();
    const U = nextInt();

    // head and next for adjacency list to save memory and be fast
    // Each number in 1..U can have a list of cards that contain it
    const head = new Int32Array(U + 1).fill(-1);
    const toCard = new Int32Array(N * K);
    const nextEdge = new Int32Array(N * K);
    let edgeCount = 0;

    for (let c = 1; c <= N; c++) {
        for (let j = 0; j < K; j++) {
            const num = nextInt();
            toCard[edgeCount] = c;
            nextEdge[edgeCount] = head[num];
            head[num] = edgeCount++;
        }
    }

    const remaining = new Int32Array(N + 1).fill(K);
    const winners = [];

    for (let i = 0; i < U; i++) {
        const drawn = nextInt();
        let e = head[drawn];
        while (e !== -1) {
            const card = toCard[e];
            remaining[card]--;
            if (remaining[card] === 0) {
                winners.push(card);
            }
            e = nextEdge[e];
        }

        if (winners.length > 0) {
            break;
        }
    }

    winners.sort((a, b) => a - b);
    console.log(winners.join(' '));
}

main();
